# FP arithmetic against Spike: 300 operand pairs (specials x specials,
# random, near-cancelling) through fadd/fsub/fmul/fdiv.s in every rounding
# mode, reading and clearing fflags after each operation.
# Generated by tools/gen_fp_lockstep.py; edit the generator, not this file.
.include "harness.inc"

.macro FP_OPS rm
    fadd.s f3, f1, f2, \rm
    csrrw a0, fflags, x0
    fsub.s f4, f1, f2, \rm
    csrrw a1, fflags, x0
    fmul.s f5, f1, f2, \rm
    csrrw a2, fflags, x0
    fdiv.s f6, f1, f2, \rm
    csrrw a3, fflags, x0
.endm

LOCKSTEP_START
FP_INIT
    la s0, fp_operands
    li s1, 300
    la s2, fp_results
1:  flw f1, 0(s0)
    flw f2, 4(s0)
    # Dynamic rounding mode cycles through 0-4.
    li t1, 5
    remu t1, s1, t1
    csrw frm, t1
    .irp rm, rne, rtz, rdn, rup, rmm, dyn
    FP_OPS \rm
    .endr
    # Results feed straight back in (FP forwarding) and get stored.
    fadd.s f7, f3, f4
    fmul.s f8, f7, f5
    fsw f8, 0(s2)
    fsw f6, 4(s2)
    csrr a4, fcsr
    csrw fflags, x0
    addi s0, s0, 8
    addi s2, s2, 8
    addi s1, s1, -1
    bnez s1, 1b
    csrr a5, mstatus
LOCKSTEP_PASS
LOCKSTEP_FOOTER

    .data
    .balign 8
